`createParcelWorkflow(parcelIds)` creates an isolated workflow instance for the supplied distinct parcel IDs. Every parcel begins in `CREATED` state. The returned object must expose:

- `execute(command)`, where `command` has string properties `commandId`, `parcelId`, and `action`.
- `getStatus(parcelId)`, which returns the parcel's current state.

Supported actions and transitions are:

- `pack`: `CREATED` to `PACKED`
- `ship`: `PACKED` to `SHIPPED`
- `cancel`: `CREATED` or `PACKED` to `CANCELLED`

`execute` returns the state produced by the command. An unknown parcel, unsupported action, or action that is invalid for the current state must throw an `Error` and must not change any state.

Successful commands are idempotent by `commandId`. After a command succeeds, every later call using the same `commandId` must return that command's original result without applying another transition, even if the later command contains different `parcelId` or `action` values. Failed commands are not remembered. Separate workflow instances must not share parcel states or remembered command IDs.

Do not use the filesystem, network, clock, randomness, frameworks, or external packages.","reference_code":"function createParcelWorkflow(parcelIds) {
  const states = new Map();
  const completedCommands = new Map();

  for (const parcelId of parcelIds) {
    states.set(parcelId, 'CREATED');
  }

  function execute(command) {
    if (completedCommands.has(command.commandId)) {
      return completedCommands.get(command.commandId);
    }

    if (!states.has(command.parcelId)) {
      throw new Error('Unknown parcel');
    }

    const current = states.get(command.parcelId);
    let next;

    if (command.action === 'pack' && current === 'CREATED') {
      next = 'PACKED';
    } else if (command.action === 'ship' && current === 'PACKED') {
      next = 'SHIPPED';
    } else if (
      command.action === 'cancel' &&
      (current === 'CREATED' || current === 'PACKED')
    ) {
      next = 'CANCELLED';
    } else if (
      command.action !== 'pack' &&
      command.action !== 'ship' &&
      command.action !== 'cancel'
    ) {
      throw new Error('Unsupported action');
    } else {
      throw new Error('Invalid transition');
    }

    states.set(command.parcelId, next);
    completedCommands.set(command.commandId, next);
    return next;
  }

  function getStatus(parcelId) {
    if (!states.has(parcelId)) {
      throw new Error('Unknown parcel');
    }
    return states.get(parcelId);
  }

  return { execute, getStatus };
}

