The returned object must expose:

- `update(field, value)`, which assigns the named field, clears existing errors, changes `status` to `EDITING`, and returns that status.
- `submit()`, which validates that `name` and `email` are non-empty and that `confirmation` exactly equals `email`. It replaces the errors array with messages in that order, changes `status` to `ACCEPTED` when there are no errors or `INVALID` otherwise, and returns the resulting status.
- `reset()`, which restores empty fields, no errors, and `EDITING` status.
- `snapshot()`, which returns the current `name`, `email`, `confirmation`, `status`, and `errors`.

A snapshot must be independent of internal workflow state: changing its properties or its `errors` array must not affect later workflow operations or snapshots. Export exactly `{ createRegistrationDraft }` with CommonJS.

```javascript
function createRegistrationDraft() {
  const state = {
    name: '',
    email: '',
    confirmation: '',
    status: 'EDITING',
    errors: []
  };

  function update(field, value) {
    state[field] = value;
    state.errors = [];
    state.status = 'EDITING';
    return state.status;
  }

  function submit() {
    const errors = [];

    if (state.name === '') {
      errors.push('Name is required');
    }
    if (state.email === '') {
      errors.push('Email is required');
    }
    if (state.confirmation !== state.email) {
      errors.push('Confirmation must match email');
    }

    state.errors = errors;
    state.status = errors.length === 0 ? 'ACCEPTED' : 'INVALID';
    return state.status;
  }

  function reset() {
    state.name = '';
    state.email = '';
    state.confirmation = '';
    state.status = 'EDITING';
    state.errors = [];
  }

  function snapshot() {
    return state;
  }

  return { update, submit, reset, snapshot };
}

module.exports = { createRegistrationDraft };
```

