{"items":[{"id":"cap-v2-stateful_workflows-javascript-repair-02","test_code":"'use strict';

const assert = require('node:assert');
const createBatch = require('./solution');

assert.strictEqual(typeof createBatch, 'function');

{
  const input = ['alpha'];
  const batch = createBatch(input);
  input.push('outside');

  assert.deepStrictEqual(batch.snapshot(), {
    phase: 'OPEN',
    committed: ['alpha'],
    pending: []
  });

  const staged = batch.stage('stage-1', 'beta');
  assert.deepStrictEqual(staged, {
    phase: 'OPEN',
    committed: ['alpha'],
    pending: ['beta']
  });

  staged.committed.push('corrupt');
  staged.pending.push('corrupt');
  assert.deepStrictEqual(batch.snapshot(), {
    phase: 'OPEN',
    committed: ['alpha'],
    pending: ['beta']
  });

  const older = batch.snapshot();
  batch.stage('stage-2', 'gamma');
  assert.deepStrictEqual(older, {
    phase: 'OPEN',
    committed: ['alpha'],
    pending: ['beta']
  });

  assert.deepStrictEqual(batch.commit('stage-1'), {
    phase: 'OPEN',
    committed: ['alpha'],
    pending: ['beta', 'gamma']
  });

  const committed = batch.commit('commit-1');
  assert.deepStrictEqual(committed, {
    phase: 'COMMITTED',
    committed: ['alpha', 'beta', 'gamma'],
    pending: []
  });

  assert.throws(() => batch.stage('new-stage', 'delta'), /Batch is closed/);
  assert.throws(() => batch.rollback('new-rollback'), /Batch is closed/);
  assert.throws(() => batch.commit('new-commit'), /Batch is closed/);

  assert.deepStrictEqual(batch.stage('stage-2', 'ignored'), committed);
  assert.deepStrictEqual(batch.rollback('stage-1'), committed);
  assert.deepStrictEqual(batch.commit('commit-1'), committed);
}

{
  const batch = createBatch([]);
  batch.stage('shared-id', 'temporary');
  assert.deepStrictEqual(batch.rollback('shared-id'), {
    phase: 'OPEN',
    committed: [],
    pending: ['temporary']
  });

  const rolledBack = batch.rollback('rollback-1');
  assert.deepStrictEqual(rolledBack, {
    phase: 'ROLLED_BACK',
    committed: [],
    pending: []
  });
  assert.deepStrictEqual(batch.rollback('rollback-1'), rolledBack);
  assert.throws(() => batch.commit('unused-id'), /Batch is closed/);
}

{
  const first = createBatch(['one']);
  const second = createBatch(['two']);
  first.stage('same-operation-id', 'x');
  second.stage('same-operation-id', 'y');
  assert.deepStrictEqual(first.snapshot().pending, ['x']);
  assert.deepStrictEqual(second.snapshot().pending, ['y']);
}
"},{"id":"cap-v2-string_and_unicode-javascript-generation-01","test_code":"'use strict';

const assert = require('node:assert');
const canonicalizeCaption = require('./solution');

assert.strictEqual(typeof canonicalizeCaption, 'function');

for (const value of [undefined, null, 0, true, {}, [], new String('text')]) {
  assert.throws(() => canonicalizeCaption(value), TypeError);
}

assert.strictEqual(canonicalizeCaption(''), '');
assert.strictEqual(canonicalizeCaption('   \t\n\r\v\f   '), '');
assert.strictEqual(
  canonicalizeCaption('\t  Hello\n\rworld\u00A0\u2028again  '),
  'Hello world again'
);
assert.strictEqual(canonicalizeCaption('A\u2003\u2009B'), 'A B');
assert.strictEqual(canonicalizeCaption('Cafe\u0301'), 'Caf\u00E9');
assert.strictEqual(canonicalizeCaption('\u212B'), '\u00C5');
assert.strictEqual(canonicalizeCaption('x😀y'), 'x😀y');
assert.strictEqual(canonicalizeCaption('a\u200Bb'), 'a\u200Bb');

const malformed = [
  '\uD800',
  '\uDC00',
  'a\uD800b',
  'a\uDC00b',
  '\uD800\uD800',
  '\uDC00\uDC00',
  '\uD83D x',
  'x\uDE00'
];
for (const value of malformed) {
  assert.throws(() => canonicalizeCaption(value), RangeError);
}

assert.strictEqual(canonicalizeCaption('\uD83D\uDE00'), '😀');
assert.strictEqual(canonicalizeCaption('\uD800\uDC00 \uDBFF\uDFFF'), '𐀀 􏿿');
"},{"id":"cap-v2-string_and_unicode-javascript-generation-02","test_code":"'use strict';

const assert = require('node:assert');
const decodeCodePointEscapes = require('./solution');

assert.strictEqual(typeof decodeCodePointEscapes, 'function');

const escape = (body) => '\\' + 'u{' + body + '}';
const prefix = '\\' + 'u{';

for (const value of [undefined, null, 1, false, {}, [], new String('x')]) {
  assert.throws(() => decodeCodePointEscapes(value), TypeError);
}

assert.strictEqual(decodeCodePointEscapes(''), '');
assert.strictEqual(decodeCodePointEscapes('plain text'), 'plain text');
assert.strictEqual(decodeCodePointEscapes(escape('41')), 'A');
assert.strictEqual(decodeCodePointEscapes(escape('000041')), 'A');
assert.strictEqual(decodeCodePointEscapes(escape('aF')), '¯');
assert.strictEqual(decodeCodePointEscapes(escape('1F600')), '😀');
assert.strictEqual(decodeCodePointEscapes(escape('10FFFF')), String.fromCodePoint(0x10FFFF));
assert.strictEqual(
  decodeCodePointEscapes('x' + escape('41') + escape('1F642') + 'y'),
  'xA🙂y'
);

assert.strictEqual(decodeCodePointEscapes('\\u0041'), '\\u0041');
assert.strictEqual(decodeCodePointEscapes('backslash: \\ end'), 'backslash: \\ end');
assert.strictEqual(
  decodeCodePointEscapes('\\' + escape('41')),
  '\\A'
);

for (const malformed of [
  prefix,
  prefix + '41',
  escape(''),
  escape('G'),
  escape('12G4'),
  escape('1234567'),
  prefix + '41]'
]) {
  assert.throws(() => decodeCodePointEscapes(malformed), SyntaxError);
}

for (const outOfRange of [
  escape('110000'),
  escape('D800'),
  escape('DFFF'),
  escape('dabc')
]) {
  assert.throws(() => decodeCodePointEscapes(outOfRange), RangeError);
}

assert.strictEqual(decodeCodePointEscapes(escape('D7FF')), String.fromCodePoint(0xD7FF));
assert.strictEqual(decodeCodePointEscapes(escape('E000')), String.fromCodePoint(0xE000));
