const assert = require('node:assert');
const countCanonicalWords = require('./solution');

assert.strictEqual(typeof countCanonicalWords, 'function');
assert.deepStrictEqual(countCanonicalWords(''), []);
assert.deepStrictEqual(countCanonicalWords(' ,.!—\t\n'), []);

assert.deepStrictEqual(
  countCanonicalWords('Zebra apple ZEBRA banana APPLE'),
  [
    { word: 'zebra', count: 2 },
    { word: 'apple', count: 2 },
    { word: 'banana', count: 1 }
  ]
);

assert.deepStrictEqual(
  countCanonicalWords('ＦＯＯ foo ﬁsh fish ① 1'),
  [
    { word: 'foo', count: 2 },
    { word: 'fish', count: 2 },
    { word: '1', count: 2 }
  ]
);

assert.deepStrictEqual(
  countCanonicalWords('Cafe\u0301 CAFÉ हिंदी १२३ हिंदी'),
  [
    { word: 'café', count: 2 },
    { word: 'हिंदी', count: 2 },
    { word: '१२३', count: 1 }
  ]
);

assert.deepStrictEqual(
  countCanonicalWords('A1β٢---A1β٢'),
  [{ word: 'a1β٢', count: 2 }]
);

assert.deepStrictEqual(
  countCanonicalWords('\u0301 ! \u0301'),
  [{ word: '\u0301', count: 2 }]
);

assert.deepStrictEqual(
  countCanonicalWords('İ İ I'),
  [
    { word: 'i\u0307', count: 2 },
    { word: 'i', count: 1 }
  ]
);

const first = countCanonicalWords('b a b');
first[0].word = 'changed';
first.push({ word: 'x', count: 99 });
assert.deepStrictEqual(countCanonicalWords('b a b'), [
  { word: 'b', count: 2 },
  { word: 'a', count: 1 }
]);
"},{"id":"cap-v2-string_and_unicode-javascript-repair-02","test_code":"'use strict';

const assert = require('node:assert');
const inventoryCodePoints = require('./solution');

assert.strictEqual(typeof inventoryCodePoints, 'function');
assert.deepStrictEqual(inventoryCodePoints(''), []);
assert.deepStrictEqual(inventoryCodePoints(' \t\n\r\u00A0\u0085\u2028\u3000'), []);

assert.deepStrictEqual(inventoryCodePoints('b a b c a'), [
  { symbol: 'b', codePoint: 'U+0062', count: 2 },
  { symbol: 'a', codePoint: 'U+0061', count: 2 },
  { symbol: 'c', codePoint: 'U+0063', count: 1 }
]);

assert.deepStrictEqual(inventoryCodePoints('😀A😀𐀀A'), [
  { symbol: '😀', codePoint: 'U+1F600', count: 2 },
  { symbol: 'A', codePoint: 'U+0041', count: 2 },
  { symbol: '𐀀', codePoint: 'U+10000', count: 1 }
]);

assert.deepStrictEqual(inventoryCodePoints('e\u0301 é E\u0301'), [
  { symbol: 'é', codePoint: 'U+00E9', count: 2 },
  { symbol: 'É', codePoint: 'U+00C9', count: 1 }
]);

assert.deepStrictEqual(inventoryCodePoints('\u0301x\u0301'), [
  { symbol: '\u0301', codePoint: 'U+0301', count: 2 },
  { symbol: 'x', codePoint: 'U+0078', count: 1 }
]);

assert.deepStrictEqual(inventoryCodePoints('\u200B A'), [
  { symbol: '\u200B', codePoint: 'U+200B', count: 1 },
  { symbol: 'A', codePoint: 'U+0041', count: 1 }
]);

const oldResult = inventoryCodePoints('aba');
oldResult[0].symbol = 'changed';
oldResult[0].count = 100;
oldResult.push({ symbol: 'x', codePoint: 'U+0078', count: 1 });
assert.deepStrictEqual(inventoryCodePoints('aba'), [
  { symbol: 'a', codePoint: 'U+0061', count: 2 },
  { symbol: 'b', codePoint: 'U+0062', count: 1 }
]);
